def q(v):return 'NULL' if v is None else "'"+str(v).replace("'","''")+"'"
sql=['-- Solomode 2025 first-post resources; external destinations were not opened.','PRAGMA foreign_keys=ON;','BEGIN IMMEDIATE;','CREATE TEMP TABLE sm_e(id PRIMARY KEY,title,wip,status);','CREATE TEMP TABLE sm_r(entry_id,url,role,form,label,context,PRIMARY KEY(entry_id,url));']
for e,t,tid,s in DATA:sql.append(f"INSERT INTO sm_e VALUES({e},{q(t)},{q('https://boardgamegeek.com/thread/'+tid if tid else None)},{q(s)});")
for row in R:sql.append('INSERT INTO sm_r VALUES('+','.join(q(v) for v in row)+');')
sql.append(f"UPDATE entries SET wip_thread_url=(SELECT wip FROM sm_e WHERE sm_e.id=entries.id) WHERE contest_id={CONTEST_ID};")
sql += [f"DELETE FROM entry_resource_scans WHERE entry_id IN (SELECT id FROM entries WHERE contest_id={CONTEST_ID}) AND checked_at='{DATE}';",f"INSERT INTO entry_resource_scans(entry_id,checked_at,source_url,wip_status,resource_listing_status,notes) SELECT id,'{DATE}',COALESCE(wip,'https://boardgamegeek.com/geeklist/353866/2025-solomode-design-contest-submissions'),CASE WHEN wip IS NULL THEN 'not_found' ELSE 'found' END,status,CASE WHEN status='not_observable' THEN 'Risorsa dichiarata ma non più osservabile dal primo post.' WHEN status='not_checked' THEN 'La voce GeekList punta alla pagina generale del contest; nessun WIP individuale inventato.' WHEN status='none_declared' THEN 'Primo post letto integralmente: nessun collegamento pertinente osservato.' ELSE 'Primo post renderizzato censito; destinazioni non aperte.' END FROM sm_e;","INSERT OR IGNORE INTO remote_resources(game_id,kind,access_type,url,host,label,availability_status,first_seen_at,last_verified_at) SELECT e.game_id,r.role,r.form,r.url,substr(r.url,instr(r.url,'//')+2,instr(substr(r.url,instr(r.url,'//')+2),'/')-1),r.label,'unknown','2026-09-15','2026-09-15' FROM sm_r r JOIN entries e ON e.id=r.entry_id;",f"DELETE FROM entry_resource_mentions WHERE entry_id IN (SELECT id FROM entries WHERE contest_id={CONTEST_ID});","INSERT INTO entry_resource_mentions(entry_id,remote_resource_id,source_url,label_raw,content_role,is_primary,first_seen_at,last_seen_at) SELECT r.entry_id,rr.id,s.wip,r.label,r.role,CASE WHEN r.role='game_files' THEN 1 ELSE 0 END,'2026-09-15','2026-09-15' FROM sm_r r JOIN sm_e s ON s.id=r.entry_id JOIN entries e ON e.id=r.entry_id JOIN remote_resources rr ON rr.game_id=e.game_id AND rr.url=r.url;","INSERT INTO remote_resource_observations(remote_resource_id,observed_at,evidence_url,observation_kind,availability_status,notes) SELECT rr.id,'2026-09-15',s.wip,'declared_in_wip','not_checked','Destinazione non aperta. Contesto: '||r.context FROM sm_r r JOIN sm_e s ON s.id=r.entry_id JOIN entries e ON e.id=r.entry_id JOIN remote_resources rr ON rr.game_id=e.game_id AND rr.url=r.url WHERE NOT EXISTS(SELECT 1 FROM remote_resource_observations o WHERE o.remote_resource_id=rr.id AND o.observed_at='2026-09-15');",'DROP TABLE sm_r;','DROP TABLE sm_e;','COMMIT;']
# Inserimento difensivo basato sulle risorse appena create: copre anche URL
# condivisi senza dipendere dalla ricomposizione della tabella temporanea.
sql.insert(-3,"INSERT OR IGNORE INTO entry_resource_mentions(entry_id,remote_resource_id,source_url,label_raw,content_role,is_primary,first_seen_at,last_seen_at) SELECT e.id,rr.id,e.wip_thread_url,rr.label,rr.kind,CASE WHEN rr.kind='game_files' THEN 1 ELSE 0 END,'2026-09-15','2026-09-15' FROM entries e JOIN remote_resources rr ON rr.game_id=e.game_id WHERE e.contest_id=16 AND rr.first_seen_at='2026-09-15';")
sql.insert(-3,"INSERT INTO remote_resource_observations(remote_resource_id,observed_at,evidence_url,observation_kind,availability_status,notes) SELECT rr.id,'2026-09-15',e.wip_thread_url,'declared_in_wip','not_checked','Destinazione non aperta. Contesto: '||COALESCE((SELECT r.context FROM sm_r r WHERE r.entry_id=e.id AND r.url=rr.url),'vedere registro versionato') FROM entries e JOIN remote_resources rr ON rr.game_id=e.game_id WHERE e.contest_id=16 AND rr.first_seen_at='2026-09-15' AND NOT EXISTS(SELECT 1 FROM remote_resource_observations o WHERE o.remote_resource_id=rr.id AND o.observed_at='2026-09-15');")
(ROOT/'catalog'/'2025-solomode-wips-resources.sql').write_text('\n'.join(sql)+'\n',encoding='utf-8')
c=Counter(e for e,*_ in R); labels={'observed':'risorse osservate','none_declared':'nessuna risorsa dichiarata','not_observable':'risorsa non osservabile','not_checked':'WIP non individuato'}
md=['# WIP e risorse dichiarate — Solomode 2025','','Verifica del 15 settembre 2026 sui primi post dei 36 WIP disponibili. Destinazioni non aperte. Le 38 proposte restano varianti dipendenti dal rispettivo gioco base.','','| # | Variante | Stato | Link |','|---:|---|---|---:|']
for i,(e,t,_,s) in enumerate(DATA,1):md.append(f'| {i} | {t} | {labels[s]} | {c[e]} |')
