for e,u,r,f,l,x in R:md.append(f'| {clean(titles[e])} | {clean(l)} | {clean(x)} | `{r}` | `{f}` | `{urlparse(u).netloc}` | {u} |')
md+=['','## Totali','',f'- 38 varianti: 36 WIP, 2 riferimenti generici senza WIP individuale.',f'- 34 WIP con risorse, 1 senza collegamenti pertinenti, 1 con risorsa rimossa/non osservabile.',f'- {len(R)} collegamenti distinti.','- Nessuna destinazione esterna aperta e nessun file scaricato.']
(ROOT/'sources'/'2025-SOLOMODE-WIPS-RESOURCES.md').write_text('\n'.join(md)+'\n',encoding='utf-8');print(len(R))
